<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <main id="maincontent" tabindex="-1">
    <section class="shell" aria-labelledby="quiz-title">
      <header class="hero">
        <p class="eyebrow">Learning check</p>
        <h1 id="quiz-title">Computer languages quiz</h1>
        <p class="intro">Choose all answers you think are correct for each question, then submit to see your score.</p>
      </header>

      <form id="quiz-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="q1-help">
            <legend>1. Which of these are programming languages?</legend>
            <p class="help" id="q1-help">Select all that apply.</p>

            <div class="choices">
              <label class="choice" for="q1-javascript">
                <input id="q1-javascript" name="q1" type="checkbox" value="javascript">
                <span>JavaScript</span>
              </label>
              <label class="choice" for="q1-python">
                <input id="q1-python" name="q1" type="checkbox" value="python">
                <span>Python</span>
              </label>
              <label class="choice" for="q1-html">
                <input id="q1-html" name="q1" type="checkbox" value="html">
                <span>HTML</span>
              </label>
              <label class="choice" for="q1-ruby">
                <input id="q1-ruby" name="q1" type="checkbox" value="ruby">
                <span>Ruby</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which of these are compiled languages?</legend>

            <div class="choices">
              <label class="choice" for="q2-go">
                <input id="q2-go" name="q2" type="checkbox" value="go">
                <span>Go</span>
              </label>
              <label class="choice" for="q2-csharp">
                <input id="q2-csharp" name="q2" type="checkbox" value="csharp">
                <span>C#</span>
              </label>
              <label class="choice" for="q2-shell">
                <input id="q2-shell" name="q2" type="checkbox" value="shell">
                <span>Shell script</span>
              </label>
              <label class="choice" for="q2-rust">
                <input id="q2-rust" name="q2" type="checkbox" value="rust">
                <span>Rust</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which of these are markup or query languages?</legend>

            <div class="choices">
              <label class="choice" for="q3-html">
                <input id="q3-html" name="q3" type="checkbox" value="html">
                <span>HTML</span>
              </label>
              <label class="choice" for="q3-css">
                <input id="q3-css" name="q3" type="checkbox" value="css">
                <span>CSS</span>
              </label>
              <label class="choice" for="q3-sql">
                <input id="q3-sql" name="q3" type="checkbox" value="sql">
                <span>SQL</span>
              </label>
              <label class="choice" for="q3-java">
                <input id="q3-java" name="q3" type="checkbox" value="java">
                <span>Java</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Check answers</button>
          <p class="result" id="quiz-result" role="status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const quizForm = document.getElementById('quiz-form');
    const result = document.getElementById('quiz-result');
    const answerKey = {
      q1: ['javascript', 'python', 'ruby'],
      q2: ['go', 'csharp', 'rust'],
      q3: ['html', 'sql']
    };

    function normalizeSelections(formData, name) {
      return formData.getAll(name).sort();
    }

    quizForm.addEventListener('submit', (event) => {
      event.preventDefault();

      const formData = new FormData(quizForm);
      let score = 0;

      for (const [question, correctAnswers] of Object.entries(answerKey)) {
        const selected = normalizeSelections(formData, question);
        const correct = [...correctAnswers].sort();

        if (selected.length === correct.length && selected.every((value, index) => value === correct[index])) {
          score += 1;
        }
      }

      result.textContent = `You scored ${score} out of ${Object.keys(answerKey).length}.`;
    });
  </script>
</body>
</html>
